# upstream M3-3a: generate GBK<->Unicode bidirectional table as C++ source.
# Output: gbk_table.cpp with two sorted arrays:
#   - gGbkToUni: sorted by GBK code point (uint32), value = Unicode CP
#   - gUniToGbk: sorted by Unicode CP, value = GBK 2-byte code (0 = unmapped)
# Only the GBK double-byte region (0x8140..0xFEFE) is tabulated; ASCII passes
# through identity, as it does in real GBK. PUA (GBK ext A) kept as-is.
# All output ASCII only (MSVC-free, no BOM, LF endings) to survive cmd node/powershell.
import sys

def gbk_codes():
    lo_vals = []
    for b in range(0x40, 0x100):
        if b == 0x7F:
            continue
        lo_vals.append(b)
    codes = []
    for hi in range(0x81, 0x100):
        for lo in lo_vals:
            codes.append(hi * 256 + lo)
    return codes

def main():
    pairs = []
    seen_uni = set()
    for code in gbk_codes():
        b = bytes([code >> 8, code & 0xFF])
        try:
            u = b.decode('gbk')
        except UnicodeDecodeError:
            continue
        if len(u) != 1:
            continue
        cp = ord(u)
        if cp in seen_uni:
            # first mapping wins (CP936 roundtrip canonical); skip duplicates
            continue
        seen_uni.add(cp)
        pairs.append((code, cp))
    # sort by GBK code for table A, by Unicode for table B
    a = sorted(pairs, key=lambda p: p[0])
    b = sorted(pairs, key=lambda p: p[1])
    out = []
    out.append('/* Auto-generated by thirdparty/gen_gbk_table.py - DO NOT EDIT.')
    out.append(' * GBK double-byte region 0x8140-0xFEFE mapped to Unicode.')
    out.append(' * Built via Python cp936 codec (Windows) cross-checked with')
    out.append(' * musl iconv absence on OHOS (musl ships only single-byte +')
    out.append(' * UTF-16/32 codecs; no GBK) - hence the static table.')
    out.append(' */')
    out.append('#include "napi/gbk_table.h"')
    out.append('')
    out.append('namespace upstream {')
    out.append('')
    out.append('/* {gbk code, unicode cp} sorted by gbk code; lookup via bsearch */')
    out.append('const GbkEntry kGbkToUni[] = {')
    for i in range(0, len(a), 6):
        row = ', '.join('{0x%04X, 0x%04X}' % p for p in a[i:i+6])
        out.append('    ' + row + ',')
    out.append('};')
    out.append('const size_t kGbkToUniCount = sizeof(kGbkToUni) / sizeof(kGbkToUni[0]);')
    out.append('')
    out.append('/* {unicode cp, gbk code} sorted by unicode cp; lookup via bsearch */')
    out.append('const UniEntry kUniToGbk[] = {')
    for i in range(0, len(b), 6):
        row = ', '.join('{0x%04X, 0x%04X}' % (p[1], p[0]) for p in b[i:i+6])
        out.append('    ' + row + ',')
    out.append('};')
    out.append('const size_t kUniToGbkCount = sizeof(kUniToGbk) / sizeof(kUniToGbk[0]);')
    out.append('')
    out.append('} // namespace upstream')
    with open(sys.argv[1] if len(sys.argv) > 1 else 'gbk_table.cpp', 'w', newline='\n') as f:
        f.write('\n'.join(out) + '\n')
    print('entries=%d' % len(a))

if __name__ == '__main__':
    main()
